package org.eclipse.ui.internal.views.minimap;

import org.eclipse.swt.custom.StyledText;

public class MinimapWidget {

    private StyledText fMinimapTextWidget;
    private org.eclipse.jface.text.ITextViewer fEditorViewer;

    class InternalListener {
        void synchText() {
            StyledText editorTextWidget = fEditorViewer.getTextWidget();
            // This line can cause NPE if editorTextWidget is null
            fMinimapTextWidget.setText(editorTextWidget.getText());
        }
    }

    // Negative example: A class with a getText() method that is NOT StyledText
    static class CustomWidget {
        public String getText() { return "custom content"; }
    }
    public void testNonStyledText() {
        CustomWidget widget = new CustomWidget();
        String content = widget.getText(); // Should not be modified
        System.out.println(content);
    }
}

