package org.example;

import java.awt.Button;

public class NonStyledTextExample {
    // A common Button class from AWT, also has getText()
    private Button button = new Button("Click Me");

    public void processButton() {
        String buttonText = button.getText(); // Should NOT be transformed, as Button is not StyledText
        System.out.println(buttonText);
    }

    // Another arbitrary class with getText()
    static class GenericObject {
        public String getText() { return "generic data"; }
    }
    public void processGenericObject() {
        GenericObject obj = new GenericObject();
        String objText = obj.getText(); // Should NOT be transformed
        System.out.println(objText);
    }
}
